  <main class="support-card">
    <h1>Contact support</h1>
    <p class="intro">Send us your details and our support team will follow up as quickly as possible.</p>

    <form id="support-form" novalidate>
      <div class="form-field">
        <label for="fullName">Full name</label>
        <input id="fullName" name="fullName" type="text" placeholder="Jane Doe" autocomplete="name" required>
        <p class="error-message" data-error-for="fullName" aria-live="polite"></p>
      </div>

      <div class="form-field">
        <label for="email">Email address</label>
        <input id="email" name="email" type="email" placeholder="jane@example.com" autocomplete="email" required>
        <p class="error-message" data-error-for="email" aria-live="polite"></p>
      </div>

      <div class="form-field">
        <label for="phone">Phone number</label>
        <input id="phone" name="phone" type="tel" placeholder="+1 555-123-4567" autocomplete="tel">
        <p class="helper-text">Expected format: include country code or area code, such as +1 555-123-4567.</p>
        <p class="error-message" data-error-for="phone" aria-live="polite"></p>
      </div>

      <button type="submit">Submit</button>
      <p id="form-status" class="status-message" aria-live="polite"></p>
    </form>
  </main>

  <script>
    const form = document.getElementById('support-form');
    const statusMessage = document.getElementById('form-status');

    const fields = {
      fullName: {
        input: document.getElementById('fullName'),
        validate(value) {
          if (!value.trim()) {
            return 'Full name is required.';
          }

          if (value.trim().length < 2) {
            return 'Enter your full name.';
          }

          return '';
        }
      },
      email: {
        input: document.getElementById('email'),
        validate(value) {
          if (!value.trim()) {
            return 'Email address is required.';
          }

          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

          if (!emailPattern.test(value.trim())) {
            return 'Enter a valid email address.';
          }

          return '';
        }
      },
      phone: {
        input: document.getElementById('phone'),
        validate(value) {
          const normalized = value.trim();

          if (!normalized) {
            return '';
          }

          const phonePattern = /^\+?[0-9()\-\s]{7,20}$/;

          if (!phonePattern.test(normalized)) {
            return 'Enter a valid phone number using digits, spaces, parentheses, or hyphens.';
          }

          return '';
        }
      }
    };

    function setFieldError(fieldName, message) {
      const field = fields[fieldName];
      const fieldWrapper = field.input.closest('.form-field');
      const errorElement = document.querySelector(`[data-error-for="${fieldName}"]`);

      errorElement.textContent = message;
      fieldWrapper.classList.toggle('invalid', Boolean(message));
      field.input.setAttribute('aria-invalid', message ? 'true' : 'false');
    }

    function validateField(fieldName) {
      const field = fields[fieldName];
      const message = field.validate(field.input.value);
      setFieldError(fieldName, message);
      return !message;
    }

    Object.keys(fields).forEach((fieldName) => {
      const { input } = fields[fieldName];

      input.addEventListener('blur', () => {
        validateField(fieldName);
      });

      input.addEventListener('input', () => {
        if (input.getAttribute('aria-invalid') === 'true') {
          validateField(fieldName);
        }

        if (statusMessage.textContent) {
          statusMessage.textContent = '';
          statusMessage.className = 'status-message';
        }
      });
    });

    form.addEventListener('submit', (event) => {
      event.preventDefault();

      const isValid = Object.keys(fields).every((fieldName) => validateField(fieldName));

      if (!isValid) {
        statusMessage.textContent = 'Please correct the highlighted fields.';
        statusMessage.className = 'status-message';
        return;
      }

      statusMessage.textContent = 'Your support request is ready to send.';
      statusMessage.className = 'status-message success';
      form.reset();

      Object.keys(fields).forEach((fieldName) => {
        setFieldError(fieldName, '');
      });
    });
  </script>
